import json, math, re
from pathlib import Path
from collections import Counter
from statistics import mean, median
from hashlib import sha256
p=Path('benchmarks/query_aligned_rate_cell_acquisition_v1.json')
r=json.loads(p.read_text(encoding='utf-8'))
def stats(values):
    return {'count':len(values),'min':min(values),'median':median(values),'mean':mean(values),'max':max(values)} if values else {'count':0}
def selected(rows):
    vals=[x['selection']['emitted'] for x in rows if x['selection']['emitted'] is not None]
    return {'stop_count':sum(x['selection']['stopped'] for x in rows),'emission_count':len(vals),'distinct_emissions':len(set(vals)), 'lengths':dict(Counter(len(re.findall(r'\w+',v)) for v in vals)), 'most_common':Counter(vals).most_common(5), 'executed_success':sum(x['execution']['passed'] for x in rows if x['expected_value'] is not None),'correct_stop':sum(x['correct_no_action'] for x in rows)}
out={'input_sha256':sha256(p.read_bytes()).hexdigest(),'scope':'Saved JSON only; no forward passes, fitting or new decisions. Conditional rank one does not establish uniqueness or executed success.','phases':{},'passes':{},'offers':{},'schedule':[]}
for phase,arms in r['phases'].items():
    pr={arm:selected(data['rows']) for arm,data in arms.items()}
    rows=arms['trainable']['rows']; sup=[x for x in rows if x['expected_value'] is not None]; uns=[x for x in rows if x['expected_value'] is None]
    pr['trainable_diagnostics']={'supported_p_stop':stats([x['diagnostics']['p_stop'] for x in sup]),'unsupported_p_stop':stats([x['diagnostics']['p_stop'] for x in uns]),'supported_rank':stats([x['diagnostics']['best_gold_rank'] for x in sup]),'rank_at_most':{str(k):sum(x['diagnostics']['best_gold_rank']<=k for x in sup) for k in [1,5,10,50,100]},'gold_minus_best_wrong':stats([x['diagnostics']['gold_to_worst_gap'] for x in sup]),'unique_correct_conditional_winner':sum(x['diagnostics']['gold_to_worst_gap']>0 for x in sup),'rank_by_gold_length':{str(k):stats([x['diagnostics']['best_gold_rank'] for x in sup if len(re.findall(r'\w+',x['expected_value']))==k]) for k in [1,2,3]},'unique_correct_by_gold_length':{str(k):sum(x['diagnostics']['gold_to_worst_gap']>0 for x in sup if len(re.findall(r'\w+',x['expected_value']))==k) for k in [1,2,3]}}
    out['phases'][phase]=pr
for passno in range(1,5):
    rows=[x for x in r['training'] if x['pass']==passno]
    out['passes'][passno]={}
    for arm in r['initial']:
        vals={}
        for label,flag in [('supported',True),('STOP',False)]:
            subset=[x for x in rows if (x['lessons'][arm]['answer'] is not None)==flag]
            first=[x['first'][arm] for x in subset]
            vals[label]={'first':selected(first),'before_loss':stats([x['new'][arm]['before_objective']['loss'] for x in subset]),'before_gate_loss':stats([x['new'][arm]['before_objective']['gate_loss'] for x in subset]),'before_span_loss':stats([x['new'][arm]['before_objective']['span_loss'] for x in subset]),'first_p_stop':stats([x['first'][arm]['selection']['p_stop'] for x in subset])}
        out['passes'][passno][arm]=vals
for arm in r['initial']:
    out['offers'][arm]={}
    for kind in ['new','replay']:
        for label,flag in [('supported',True),('STOP',False)]:
            offers=[x[kind][arm] for x in r['training'] if arm in x[kind] and (x[kind][arm]['gold_indices'] is not None)==flag]
            out['offers'][arm][kind+'_'+label]={'count':len(offers),'own_loss_improved':sum(x['loss_after']<x['before_objective']['loss'] for x in offers),'own_loss_worsened':sum(x['loss_after']>x['before_objective']['loss'] for x in offers),'loss_change':stats([x['loss_after']-x['before_objective']['loss'] for x in offers]),'gate_change':stats([x['gate_loss_after']-x['before_objective']['gate_loss'] for x in offers]),'span_change':stats([x['span_loss_after']-x['before_objective']['span_loss'] for x in offers])}
# Compact chronological query-class runs and treatment action/range.
for x in r['training']:
    out['schedule'].append({'step':x['step'],'task':x['task'],'answerable':x['lessons']['trainable']['answer'] is not None,'first_p_stop':x['first']['trainable']['selection']['p_stop'],'emitted':x['first']['trainable']['selection']['emitted'],'passed':x['first']['trainable']['execution']['passed'],'new_gate_before':x['new']['trainable']['before_objective']['gate_loss'],'new_gate_after':x['new']['trainable']['gate_loss_after']})
# Matched old/new loss on exact same task query, not current final loss.
for arm in r['initial']:
    for label,flag in [('supported',True),('STOP',False)]:
        bytask={}
        for row in r['training']:
            if (row['lessons'][arm]['answer'] is not None)==flag: bytask.setdefault(row['task'],[]).append(row['new'][arm]['before_objective'])
        changes=[v[-1]['loss']-v[0]['loss'] for v in bytask.values()]
        out['offers'][arm][label+'_first_to_fourth_encounter']={'loss_change':stats(changes),'improved_tasks':sum(v<0 for v in changes),'gate_change':stats([v[-1]['gate_loss']-v[0]['gate_loss'] for v in bytask.values()]),'span_change':stats([v[-1]['span_loss']-v[0]['span_loss'] for v in bytask.values()])}
q=Path('.pytest-tmp/query-aligned-rate-cell-behavioral-audit.json');q.write_text(json.dumps(out,indent=2,allow_nan=False)+'\n',encoding='utf-8')
print(json.dumps({'phases':{k:v['trainable_diagnostics'] for k,v in out['phases'].items()},'passes':{k:{a:{s:{'first':d['first'],'gate_mean':d['before_gate_loss']['mean'],'span_mean':d['before_span_loss']['mean']} for s,d in vals.items()} for a,vals in v.items() if a in ['trainable','frozen_producer','bypass']} for k,v in out['passes'].items()},'treatment_offers':out['offers']['trainable'],'last16':out['schedule'][-16:]},indent=2))

# Publication-focused joint gate/whole-span and growth accounting, saved JSON only.
out['status']='passed_saved_behavioral_summary'
out['checker_sha256']=sha256(Path(__file__).read_bytes()).hexdigest()
out['source_revision']=r['source_revision']
out['conditional_reference_scope']='Only treatment has saved conditional ranks; no ranks inferred for controls.'
out['conditional_correct_but_blocked']={}
for phase,arms in r['phases'].items():
    out['conditional_correct_but_blocked'][phase]=[
        {'case':x['case'],'answer':x['expected_value'],'p_stop':x['selection']['p_stop'],
         'gap':x['diagnostics']['gold_to_worst_gap'],'emitted':x['selection']['emitted']}
        for x in arms['trainable']['rows'] if x['diagnostics'].get('gold_to_worst_gap',-1)>0]
out['growth_changes']={}
for form in ['actual','alternate']:
    before=r['phases'][form+'_before_growth']['trainable']['rows']
    after=r['phases'][form+'_after_growth']['trainable']['rows']
    out['growth_changes'][form]=[
        {'case':x['case'],'expected':x['expected_value'],'before':x['selection']['emitted'],
         'after':y['selection']['emitted'],'p_before':x['selection']['p_stop'],
         'p_after':y['selection']['p_stop']}
        for x,y in zip(before,after,strict=True) if x['selection']['emitted']!=y['selection']['emitted']]
out['training_supported_successes']=[
    {'step':x['step'],'task':x['task'],'emitted':x['first']['trainable']['selection']['emitted']}
    for x in r['training'] if x['lessons']['trainable']['answer'] is not None
    and x['first']['trainable']['execution']['passed']]
assert sha256(p.read_bytes()).hexdigest()==out['input_sha256']
q.write_text(json.dumps(out,indent=2,allow_nan=False)+'\n',encoding='utf-8')

